const api = "openapi: 3.1.0\ninfo:\n  title: trendradar serve API\n  version: 2.0.0\n  description: |\n    Read-only HTTP surface exposed by `trendradar serve`. All payloads reuse the\n    digest.v2 schema, so the plugin can consume the same shape whether data comes\n    from the filesystem or over HTTP. Historical v1 digests read from disk are\n    normalized to this v2 shape with contentHashAlgo=legacy-struct-marshal-v1.\nservers:\n  - url: http://127.0.0.1:8787\npaths:\n  /api/v2/digests/{date}:\n    get:\n      operationId: getDigest\n      summary: Fetch one day's digest\n      parameters:\n        - name: date\n          in: path\n          required: true\n          schema:\n            type: string\n            format: date\n      responses:\n        \"200\":\n          description: The digest document\n          content:\n            application/json:\n              schema:\n                $ref: \"./digest.v2.json\"\n        \"404\":\n          description: No digest for that date\n  /api/v2/manifest:\n    get:\n      operationId: getManifest\n      summary: List available dates and their content identity\n      responses:\n        \"200\":\n          description: Manifest of available digests\n          content:\n            application/json:\n              schema:\n                type: object\n                required: [entries]\n                properties:\n                  coreVersion:\n                    type: string\n                  entries:\n                    type: array\n                    items:\n                      type: object\n                      required: [date, contentHash, schema, contentHashAlgo]\n                      properties:\n                        date:\n                          type: string\n                          format: date\n                        contentHash:\n                          type: string\n                        schema:\n                          type: integer\n                        contentHashAlgo:\n                          type: string\n                          enum: [jcs-sha256-v1, legacy-struct-marshal-v1]\n                        degraded:\n                          type: boolean\n  /feed.xml:\n    get:\n      operationId: getFeed\n      summary: RSS feed of the most recent digests\n      responses:\n        \"200\":\n          description: RSS 2.0 feed\n          content:\n            application/rss+xml:\n              schema:\n                type: string\n"

export const rawSchema = { model, ipc, digest, errors, versionInfo, api }

const ajv = new Ajv({ allErrors: true, strict: false })
addFormats(ajv)
ajv.addSchema(model)
ajv.addSchema(ipc)
ajv.addSchema(digest)
ajv.addSchema(versionInfo)

export const validators = {
  runRequest: ajv.compile({ $ref: ipc.$id + '#/$defs/RunRequest' }),
  runResult: ajv.compile({ $ref: ipc.$id + '#/$defs/RunResult' }),
  digest: ajv.getSchema(digest.$id),
  versionInfo: ajv.getSchema(versionInfo.$id),
}
